const ui={zh:{title:'保存你的项目，随时继续。',intro:'使用邮箱注册。请点击邮件中的确认链接；以后可用邮箱和密码登录。',home:'返回首页',register:'注册',login:'登录',email:'邮箱',password:'密码（至少 8 位）',plainPassword:'密码',send:'发送确认邮件',projects:'你的项目',logout:'退出登录',newProject:'输入项目名称',create:'新建项目',note:'你的登录信息不会显示在网站页面中。中国区账户服务暂未启用。',sent:'确认邮件已发送，请点击邮件中的确认链接。',confirmed:'邮箱验证成功，请登录。',confirmFailed:'确认链接无效或已过期。请使用邮箱和密码登录。',welcome:'欢迎回来。',saved:'项目已保存。',empty:'还没有项目。你可以从首页的 AI 对话中保存项目，或在这里新建一个。',unavailable:'会员服务暂时不可用。',signin:'请先登录。'},en:{title:'Save your projects. Continue anytime.',intro:'Register with your email. Click the confirmation link in the email; later, sign in with your email and password.',home:'Home',register:'Register',login:'Sign in',email:'Email',password:'Password (at least 8 characters)',plainPassword:'Password',send:'Send confirmation email',projects:'Your projects',logout:'Sign out',newProject:'Project name',create:'Create project',note:'Your sign-in information is never shown on the website. China-region accounts are not active yet.',sent:'Confirmation email sent. Click the confirmation link in the email.',confirmed:'Email verified. Please sign in.',confirmFailed:'The confirmation link is invalid or expired. Please sign in with your email and password.',welcome:'Welcome back.',saved:'Project saved.',empty:'No projects yet. Save an AI conversation from the home page, or create one here.',unavailable:'Membership service is temporarily unavailable.',signin:'Please sign in first.'}};
let language=localStorage.getItem('ai-supermall-language')||'zh',pendingEmail='';const $=s=>document.querySelector(s);const status=(message,ok=false)=>{const box=$('#accountStatus');box.textContent=message;box.classList.toggle('success',ok)};const request=async(path,options={})=>{const r=await fetch(path,options);const body=await r.json().catch(()=>({}));if(!r.ok){const message=body.error||body.message||ui[language].unavailable;const code=body.providerCode||body.code;throw new Error(code&&!message.includes(code)?`${message} [${code}]`:message)}return body};
function applyLanguage(next){language=next;localStorage.setItem('ai-supermall-language',next);document.documentElement.lang=next==='zh'?'zh-CN':'en';const t=ui[next];$('#pageTitle').textContent=t.title;$('#pageIntro').textContent=t.intro;$('#homeLink').textContent=t.home;$('#registerTab').textContent=t.register;$('#loginTab').textContent=t.login;$('#registerEmailLabel').textContent=t.email;$('#loginEmailLabel').textContent=t.email;$('#registerPasswordLabel').textContent=t.password;$('#loginPasswordLabel').textContent=t.plainPassword;$('#registerSubmit').textContent=t.send;$('#welcomeTitle').textContent=t.projects;$('#logoutButton').textContent=t.logout;$('#projectTitle').placeholder=t.newProject;$('#projectSubmit').textContent=t.create;$('#accountNote').textContent=t.note;$('#languageToggle').textContent=next==='zh'?'EN':'中文';}
function showTab(tab){$('#registerForm').hidden=tab!=='register';$('#loginForm').hidden=tab!=='login';$('#authTabs').hidden=false;document.querySelectorAll('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===tab));status('')}
async function loadProjects(){const data=await request('/api/member/projects');const list=$('#projectList');list.innerHTML='';if(!data.length){list.textContent=ui[language].empty;return}data.forEach(project=>{const item=document.createElement('div'),name=document.createElement('strong'),time=document.createElement('small'),open=document.createElement('a');item.className='project-item';name.textContent=project.title;time.textContent=new Date(project.updated_at).toLocaleString(language==='zh'?'zh-CN':'en-US');open.className='project-open';const state=(project.conversation||[]).find(item=>item?.type==='workspace_state'&&item.workspace==='visual');open.href=state?`create-visual.html?project=${encodeURIComponent(project.id)}`:`index.html?project=${encodeURIComponent(project.id)}`;open.textContent=language==='zh'?'打开项目':'Open project';item.append(name,time,open);list.append(item)})}
async function signedIn(){try{const user=await request('/api/account/me');$('#memberEmail').textContent=user.email;$('#authTabs').hidden=true;$('#registerForm').hidden=true;$('#loginForm').hidden=true;$('#memberArea').hidden=false;status(ui[language].welcome,true);try{await loadProjects()}catch(error){status(error.message)}}catch{}}
$('#languageToggle').onclick=()=>applyLanguage(language==='zh'?'en':'zh');document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>showTab(button.dataset.tab));
$('#registerForm').onsubmit=async event=>{event.preventDefault();try{await request('/api/account/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#registerEmail').value,password:$('#registerPassword').value})});status(ui[language].sent,true)}catch(error){status(error.message)}};
$('#loginForm').onsubmit=async event=>{event.preventDefault();try{await request('/api/account/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});await signedIn()}catch(error){status(error.message)}};
$('#logoutButton').onclick=async()=>{await request('/api/account/logout',{method:'POST'});$('#memberArea').hidden=true;showTab('login');status('')};$('#projectForm').onsubmit=async event=>{event.preventDefault();const button=$('#projectSubmit');button.disabled=true;try{await request('/api/member/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:$('#projectTitle').value,locale:language,conversation:[]})});$('#projectTitle').value='';await loadProjects();status(ui[language].saved,true)}catch(error){status(error.message)}finally{button.disabled=false}};
async function finishEmailConfirmation(){const params=new URLSearchParams(location.hash.slice(1));const token=params.get('access_token');const failed=params.get('error');if(!token&&!failed)return false;history.replaceState(null,'',location.pathname);showTab('login');status(token?ui[language].confirmed:ui[language].confirmFailed,Boolean(token));return true}
async function loadConversations(){const data=await request('/api/member/conversations');const list=$('#chatList');list.innerHTML='';if(!data.length){list.textContent=language==='zh'?'还没有对话。回到首页问一个问题后，它会自动保存在这里。':'No chats yet. Ask a question from Home and it will be saved here automatically.';return}data.forEach(chat=>{const item=document.createElement('div'),name=document.createElement('strong'),time=document.createElement('small'),open=document.createElement('a');item.className='project-item';name.textContent=chat.title;time.textContent=new Date(chat.updated_at).toLocaleString(language==='zh'?'zh-CN':'en-US');open.className='project-open';open.href=`index.html?conversation=${encodeURIComponent(chat.id)}`;open.textContent=language==='zh'?'打开对话':'Open chat';item.append(name,time,open);list.append(item)})}
function showMemberView(view){const projects=view==='projects',chats=view==='chats';$('#projectsView').hidden=!projects;$('#chatsView').hidden=!chats;$('#accountView').hidden=projects||chats;$('#memberProjectsLink').classList.toggle('active',projects);$('#memberChatsLink').classList.toggle('active',chats);$('#memberAccountLink').classList.toggle('active',!projects&&!chats);if(chats)loadConversations().catch(error=>status(error.message))}
const originalSignedIn=signedIn;signedIn=async()=>{await originalSignedIn();if(!$('#memberArea').hidden){$('#pageTitle').hidden=true;$('#pageIntro').hidden=true;$('#accountNote').hidden=true;const view=new URLSearchParams(location.search).get('view');showMemberView(view==='projects'||view==='chats'?view:'account')}};
$('#memberProjectsLink').onclick=event=>{event.preventDefault();history.replaceState(null,'','?view=projects');showMemberView('projects')};$('#memberChatsLink').onclick=event=>{event.preventDefault();history.replaceState(null,'','?view=chats');showMemberView('chats')};$('#memberAccountLink').onclick=event=>{event.preventDefault();history.replaceState(null,'','?view=account');showMemberView('account')};
const baseApplyLanguage=applyLanguage;applyLanguage=next=>{baseApplyLanguage(next);const zh=next==='zh';$('#loginSubmit').textContent=zh?'登录':'Sign in';$('#memberProjectsLink').textContent=zh?'我的项目':'My Projects';$('#memberChatsLink').textContent=zh?'对话历史':'Chat history';$('#memberAccountLink').textContent=zh?'账户':'Account';$('#projectsIntro').textContent=zh?'打开项目后可继续对话。':'Open a project to continue the conversation.';$('#chatsTitle').textContent=zh?'对话历史':'Chat history';$('#chatsIntro').textContent=zh?'普通聊天会自动保存，可随时重新打开。':'Everyday chats save automatically and can be reopened anytime.';$('#accountTitle').textContent=zh?'账户':'Account';$('#accountSummary').textContent=zh?'会员账户已登录。你可以在这里管理语言和账户设置。':'You are signed in. Manage your language and account settings here.'};
applyLanguage(language);showTab(new URLSearchParams(location.search).get('mode')==='register'?'register':'login');finishEmailConfirmation().then(done=>{if(!done)signedIn()});
